def count_apples_reachable(apple_heights: list, tao_reach: int) -> int:
    """
    Calculate the number of apples that Tao Tao can reach.

    Args:
        apple_heights (List[int]): The heights of apples from the ground (in centimeters).
        tao_reach (int): The maximum height Tao Tao can reach with her hand stretched upwards (in centimeters).

    Returns:
        int: The number of apples Tao Tao can reach with or without standing on a 30cm stool.
    """
    if not isinstance(apple_heights, list) or not isinstance(tao_reach, (int, float)):
        return 0
    try:
        effective_reach = tao_reach + 30  # Stroke adds an extra 30cm
        count = 0
        for h in apple_heights:
            try:
                if h <= effective_reach:
                    count += 1
            except Exception:
                # Skip values that are not comparable (e.g., None, strings)
                continue
        return count
    except Exception:
        return 0

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest strictly increasing subsequence ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest strictly decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = max(inc[i] + dec[i] - 1 for i in range(n))

    # Minimum removals to achieve a bitonic (choir) formation
    return n - max_bitonic
